/* Sliding-window dictionary used by the LZMA/LZMA2 decoders. */
#ifndef XZR_LZ_DECODER_H
#define XZR_LZ_DECODER_H

#include "common.h"

typedef struct {
	uint8_t *buf;      /* Dictionary buffer */
	size_t pos;        /* Write position */
	size_t full;       /* How many bytes are valid in buf */
	size_t limit;      /* Write limit for the current call */
	size_t size;       /* Allocated size of buf */
	bool need_reset;   /* Dict reset pending */
} xr_dict;

typedef struct {
	/* Called to decode into the dictionary. */
	void *coder;
	xr_ret (*code)(void *coder, xr_dict *restrict dict,
			const uint8_t *restrict in, size_t *restrict in_pos,
			size_t in_size);
	void (*reset)(void *coder, const void *options);
	void (*set_uncompressed)(void *coder, xr_vli uncompressed_size,
			bool allow_eopm);
	void (*end)(void *coder);
} xr_lz_decoder;

typedef struct {
	size_t dict_size;
	const uint8_t *preset_dict;
	size_t preset_dict_size;
} xr_lz_options;

/* Copy as much as possible from the dictionary to the output buffer. */
static inline void xr_dict_flush(xr_dict *dict, uint8_t *restrict out,
		size_t *restrict out_pos, size_t out_size, size_t *dict_start)
{
	const size_t copy_size = dict->pos - *dict_start;
	(void)out_size;
	if (copy_size > 0) {
		memcpy(out + *out_pos, dict->buf + *dict_start, copy_size);
		*out_pos += copy_size;
	}
	*dict_start = dict->pos;
}

static inline bool xr_dict_has_space(const xr_dict *dict)
{
	return dict->pos < dict->limit;
}

static inline uint32_t xr_dict_get(const xr_dict *dict, uint32_t distance)
{
	size_t offset = dict->pos - distance - 1;
	if (distance >= dict->pos)
		offset += dict->size;
	return dict->full > 0 ? dict->buf[offset] : 0;
}

static inline bool xr_dict_put(xr_dict *dict, uint8_t byte)
{
	if (dict->pos == dict->limit)
		return false;
	dict->buf[dict->pos++] = byte;
	if (dict->pos > dict->full)
		dict->full = dict->pos;
	return true;
}

static inline bool xr_dict_repeat(xr_dict *dict, uint32_t distance,
		uint32_t *len)
{
	size_t left = xr_min(dict->limit - dict->pos, *len);
	*len -= (uint32_t)left;

	size_t back = dict->pos - distance - 1;
	if (distance >= dict->pos)
		back += dict->size;

	do {
		dict->buf[dict->pos++] = dict->buf[back++];
		if (back == dict->size)
			back = 0;
	} while (--left > 0);

	if (dict->pos > dict->full)
		dict->full = dict->pos;

	return *len == 0;
}

static inline void xr_dict_reset(xr_dict *dict)
{
	dict->need_reset = false;
	dict->pos = 0;
	dict->full = 0;
}

/* Verify that a distance is inside the already-produced data. */
static inline bool xr_dict_is_distance_valid(const xr_dict *dict,
		uint32_t distance)
{
	return (size_t)distance < dict->full;
}

xr_ret xr_lz_decoder_init(xr_next_coder *next, const xr_filter *filters,
		xr_ret (*lz_init)(xr_lz_decoder *lz, xr_lz_options *lz_options,
			const void *options));

uint64_t xr_lz_decoder_memusage(size_t dict_size);

#endif

