static inline bool xr_dict_put(xr_dict *dict, uint8_t byte)
{
	if (dict->pos == dict->limit)
		return false;
	dict->buf[dict->pos++] = byte;
	if (dict->pos > dict->full)
		dict->full = dict->pos;
	return true;
}

static inline bool xr_dict_repeat(xr_dict *dict, uint32_t distance,
		uint32_t *len)
{
	size_t left = xr_min(dict->limit - dict->pos, *len);
	*len -= (uint32_t)left;

	size_t back = dict->pos - distance - 1;
	if (distance >= dict->pos)
		back += dict->size;

	do {
		dict->buf[dict->pos++] = dict->buf[back++];
		if (back == dict->size)
			back = 0;
	} while (--left > 0);

	if (dict->pos > dict->full)
		dict->full = dict->pos;

	return *len == 0;
}

static inline void xr_dict_reset(xr_dict *dict)
{
	dict->need_reset = false;
	dict->pos = 0;
	dict->full = 0;
}

/* Verify that a distance is inside the already-produced data. */
static inline bool xr_dict_is_distance_valid(const xr_dict *dict,
		uint32_t distance)
{
	return (size_t)distance < dict->full;
}

