typedef struct {
	xr_dict dict;
	xr_lz_decoder lz;
	xr_next_coder next;
	bool next_finished;
	bool this_finished;
	size_t temp_pos;
	size_t temp_size;
	uint8_t temp[XR_BLOCK_HEADER_SIZE_MAX];
} lz_coder;

static void lz_decoder_reset(lz_coder *coder, const xr_lz_options *opt)
{
	coder->dict.size = opt->dict_size;
	xr_dict_reset(&coder->dict);
	if (opt->preset_dict != NULL && opt->preset_dict_size > 0) {
		size_t copy = xr_min(opt->preset_dict_size, opt->dict_size);
		memcpy(coder->dict.buf, opt->preset_dict
				+ opt->preset_dict_size - copy, copy);
		coder->dict.pos = copy;
		coder->dict.full = copy;
	}
}

static xr_ret decode_buffer(lz_coder *coder, const uint8_t *restrict in,
		size_t *restrict in_pos, size_t in_size,
		uint8_t *restrict out, size_t *restrict out_pos,
		size_t out_size)
{
	while (true) {
		size_t dict_start = coder->dict.pos;

		coder->dict.limit = coder->dict.pos
				+ xr_min(out_size - *out_pos,
					coder->dict.size - coder->dict.pos);

		const xr_ret ret = coder->lz.code(coder->lz.coder, &coder->dict,
				in, in_pos, in_size);

		const size_t copy_size = coder->dict.pos - dict_start;
		memcpy(out + *out_pos, coder->dict.buf + dict_start, copy_size);
		*out_pos += copy_size;

		if (ret != XR_OK)
			return ret;

		if (coder->dict.pos == coder->dict.size) {
			coder->dict.pos = 0;
			coder->dict.full = coder->dict.size;
		}

		if (*out_pos == out_size)
			return XR_OK;

		if (coder->dict.pos < coder->dict.size)
			return XR_OK;
	}
}

static xr_ret lz_decode(void *coder_ptr, const uint8_t *restrict in,
		size_t *restrict in_pos, size_t in_size,
		uint8_t *restrict out, size_t *restrict out_pos,
		size_t out_size, xr_action action)
{
	lz_coder *coder = coder_ptr;
	(void)action;

	if (coder->next.code == NULL)
		return decode_buffer(coder, in, in_pos, in_size,
				out, out_pos, out_size);

	/* Not used by this build: LZ decoders are always the last filter. */
	return XR_PROG_ERROR;
}

static void lz_decoder_end(void *coder_ptr)
{
	lz_coder *coder = coder_ptr;
	xr_next_end(&coder->next);
	free(coder->dict.buf);
	if (coder->lz.end != NULL)
		coder->lz.end(coder->lz.coder);
	else
		free(coder->lz.coder);
	free(coder);
}

uint64_t xr_lz_decoder_memusage(size_t dict_size)
{
	return sizeof(lz_coder) + (uint64_t)dict_size;
}

xr_ret xr_lz_decoder_init(xr_next_coder *next, const xr_filter *filters,
		xr_ret (*lz_init)(xr_lz_decoder *lz, xr_lz_options *lz_options,
			const void *options))
{
	lz_coder *coder = next->coder;

	if (coder == NULL || next->code != &lz_decode) {
		coder = calloc(1, sizeof(lz_coder));
		if (coder == NULL)
			return XR_MEM_ERROR;
		next->coder = coder;
		next->code = &lz_decode;
		next->end = &lz_decoder_end;
		coder->next = XR_NEXT_CODER_INIT;
		coder->dict.buf = NULL;
		coder->lz.coder = NULL;
		coder->lz.code = NULL;
		coder->lz.end = NULL;
	}

	xr_lz_options lz_options;
	memset(&lz_options, 0, sizeof(lz_options));
	const xr_ret ret = lz_init(&coder->lz, &lz_options, filters[0].options);
	if (ret != XR_OK)
		return ret;

	if (lz_options.dict_size < 4096)
		lz_options.dict_size = 4096;
	/* Round up to a multiple of 16 like the reference layout does; this
	 * only affects allocation, not output. */
	lz_options.dict_size = (lz_options.dict_size + 15) & ~(size_t)15;

	if (coder->dict.buf == NULL || coder->dict.size != lz_options.dict_size) {
		free(coder->dict.buf);
		coder->dict.buf = malloc(lz_options.dict_size);
		if (coder->dict.buf == NULL)
			return XR_MEM_ERROR;
		coder->dict.size = lz_options.dict_size;
	}

	lz_decoder_reset(coder, &lz_options);
	return XR_OK;
}

