/* Binary range decoder for LZMA. */
#ifndef XZR_RANGE_DECODER_H
#define XZR_RANGE_DECODER_H

#include "common.h"

typedef uint16_t probability;

#define RC_SHIFT_BITS 8
#define RC_TOP_BITS 24
#define RC_TOP_VALUE (UINT32_C(1) << RC_TOP_BITS)
#define RC_BIT_MODEL_TOTAL_BITS 11
#define RC_BIT_MODEL_TOTAL (UINT32_C(1) << RC_BIT_MODEL_TOTAL_BITS)
#define RC_MOVE_BITS 5

#define RC_INIT_BYTES 5

typedef struct {
	uint32_t range;
	uint32_t code;
	uint32_t init_bytes_left;
} xr_range_decoder;

static inline void rc_reset(xr_range_decoder *rc)
{
	rc->range = UINT32_MAX;
	rc->code = 0;
	rc->init_bytes_left = RC_INIT_BYTES;
}

/* Feed the five initialisation bytes. Returns true when done. */
static inline bool rc_read_init(xr_range_decoder *rc, const uint8_t *in,
		size_t *in_pos, size_t in_size)
{
	while (rc->init_bytes_left > 0) {
		if (*in_pos == in_size)
			return false;
		rc->code = (rc->code << 8) | in[*in_pos];
		++*in_pos;
		--rc->init_bytes_left;
	}
	return true;
}

static inline bool rc_is_finished(const xr_range_decoder *rc)
{
	return rc->code == 0;
}

/* The decoding macros operate on local copies of range/code for speed. */
#define rc_to_local(range_decoder, in_pos_local) \
	xr_range_decoder rc = range_decoder; \
	uint32_t rc_bound; \
	size_t rc_in_pos = (in_pos_local)

#define rc_from_local(range_decoder, in_pos_local) \
	do { \
		range_decoder = rc; \
		in_pos_local = rc_in_pos; \
	} while (0)

#define rc_normalize() \
	do { \
		if (rc.range < RC_TOP_VALUE) { \
			rc.range <<= RC_SHIFT_BITS; \
			rc.code = (rc.code << RC_SHIFT_BITS) | in[rc_in_pos++]; \
		} \
	} while (0)

#define rc_if_0(prob) \
	rc_normalize(); \
	rc_bound = (rc.range >> RC_BIT_MODEL_TOTAL_BITS) * (uint32_t)(prob); \
	if (rc.code < rc_bound)

#define rc_update_0(prob) \
	do { \
		rc.range = rc_bound; \
		prob += (uint16_t)((RC_BIT_MODEL_TOTAL - (prob)) >> RC_MOVE_BITS); \
	} while (0)

#define rc_update_1(prob) \
	do { \
