/* Constants and probability-model layout shared by the LZMA
 * encoder and decoder. */
#ifndef XZR_LZMA_COMMON_H
#define XZR_LZMA_COMMON_H

#include "common.h"

/* ---- State machine ---- */
#define STATES 12
#define LIT_STATES 7

#define literal_state(state) \
	((state) <= 3 ? 0 : ((state) <= 9 ? (state) - 3 : (state) - 6))

static inline void update_literal(uint32_t *state)
{
	*state = *state <= 3 ? 0 : (*state <= 9 ? *state - 3 : *state - 6);
}

static inline void update_match(uint32_t *state)
{
	*state = *state < LIT_STATES ? 7 : 10;
}

static inline void update_long_rep(uint32_t *state)
{
	*state = *state < LIT_STATES ? 8 : 11;
}

static inline void update_short_rep(uint32_t *state)
{
	*state = *state < LIT_STATES ? 9 : 11;
}

static inline bool is_literal_state(uint32_t state)
{
	return state < LIT_STATES;
}

/* ---- Literal coder ---- */
#define LITERAL_CODER_SIZE 0x300
#define LITERAL_CODERS_MAX (1u << 4)

#define literal_subcoder(probs, lc, lp_mask, pos, prev_byte) \
	((probs)[(((pos) & (lp_mask)) << (lc)) \
			+ ((uint32_t)(prev_byte) >> (8 - (lc)))])

/* ---- Match length coder ---- */
#define LEN_LOW_BITS 3
#define LEN_LOW_SYMBOLS (1u << LEN_LOW_BITS)
#define LEN_MID_BITS 3
#define LEN_MID_SYMBOLS (1u << LEN_MID_BITS)
#define LEN_HIGH_BITS 8
#define LEN_HIGH_SYMBOLS (1u << LEN_HIGH_BITS)
#define LEN_SYMBOLS (LEN_LOW_SYMBOLS + LEN_MID_SYMBOLS + LEN_HIGH_SYMBOLS)

#define MATCH_LEN_MIN 2
#define MATCH_LEN_MAX (MATCH_LEN_MIN + LEN_SYMBOLS - 1)

/* ---- Distance coder ---- */
#define DIST_STATES 4
#define DIST_SLOT_BITS 6
#define DIST_SLOTS (1u << DIST_SLOT_BITS)
#define DIST_MODEL_START 4
#define DIST_MODEL_END 14
#define FULL_DISTANCES_BITS (DIST_MODEL_END / 2)
#define FULL_DISTANCES (1u << FULL_DISTANCES_BITS)
#define ALIGN_BITS 4
#define ALIGN_SIZE (1u << ALIGN_BITS)
#define ALIGN_MASK (ALIGN_SIZE - 1)

#define REPS 4

#define get_dist_state(len) \
	((uint32_t)((len) < DIST_STATES + MATCH_LEN_MIN \
