/* Sliding-window dictionary used by the LZMA/LZMA2 decoders. */
#ifndef XZR_LZ_DECODER_H
#define XZR_LZ_DECODER_H

#include "common.h"

typedef struct {
	uint8_t *buf;      /* Dictionary buffer */
	size_t pos;        /* Write position */
	size_t full;       /* How many bytes are valid in buf */
	size_t limit;      /* Write limit for the current call */
	size_t size;       /* Allocated size of buf */
} xr_dict;

typedef struct {
	void *coder;
	/* `eof` tells the LZ layer that in_size is the end of all the input
	 * that will ever be available for the current compressed unit. */
	xr_ret (*code)(void *coder, xr_dict *restrict dict,
			const uint8_t *restrict in, size_t *restrict in_pos,
			size_t in_size, bool eof);
	void (*reset)(void *coder, const void *options);
	void (*set_uncompressed)(void *coder, xr_vli uncompressed_size,
			bool allow_eopm);
	void (*end)(void *coder);
} xr_lz_decoder;

typedef struct {
	size_t dict_size;
	const uint8_t *preset_dict;
	size_t preset_dict_size;
} xr_lz_options;

static inline uint8_t xr_dict_get(const xr_dict *dict, uint32_t distance)
{
	size_t offset = dict->pos - distance - 1;
	if (distance >= dict->pos)
		offset += dict->size;
	return dict->full > 0 ? dict->buf[offset] : 0;
}

static inline bool xr_dict_put(xr_dict *dict, uint8_t byte)
{
	if (dict->pos == dict->limit)
		return false;
	dict->buf[dict->pos++] = byte;
	if (dict->pos > dict->full)
		dict->full = dict->pos;
	return true;
}

/* Copies *len bytes from `distance` back. Returns true if all were copied. */
static inline bool xr_dict_repeat(xr_dict *dict, uint32_t distance,
		uint32_t *len)
{
	size_t left = dict->limit - dict->pos;
	if (left > *len)
		left = *len;
	*len -= (uint32_t)left;

	size_t back = dict->pos - distance - 1;
	if (distance >= dict->pos)
		back += dict->size;

	while (left-- > 0) {
		dict->buf[dict->pos++] = dict->buf[back++];
		if (back == dict->size)
			back = 0;
	}

	if (dict->pos > dict->full)
		dict->full = dict->pos;

	return *len == 0;
}

static inline void xr_dict_reset(xr_dict *dict)
{
	dict->pos = 0;
	dict->full = 0;
}

static inline bool xr_dict_is_distance_valid(const xr_dict *dict,
		uint32_t distance)
{
	return (size_t)distance < dict->full;
}

xr_ret xr_lz_decoder_init(xr_next_coder *next, const xr_filter *filters,
		xr_ret (*lz_init)(xr_lz_decoder *lz, xr_lz_options *lz_options,
			const void *options));

uint64_t xr_lz_decoder_memusage(uint64_t dict_size);

#endif

