static inline void xr_dict_flush(xr_dict *dict, uint8_t *restrict out,
		size_t *restrict out_pos, size_t out_size, size_t *dict_start)
{
	const size_t copy_size = dict->pos - *dict_start;
	(void)out_size;
	if (copy_size > 0) {
		memcpy(out + *out_pos, dict->buf + *dict_start, copy_size);
		*out_pos += copy_size;
	}
	*dict_start = dict->pos;
}

