typedef struct {
	xr_dict dict;
	xr_lz_decoder lz;
} lz_coder;

static xr_ret lz_decode(void *coder_ptr, const uint8_t *restrict in,
		size_t *restrict in_pos, size_t in_size,
		uint8_t *restrict out, size_t *restrict out_pos,
		size_t out_size, xr_action action)
{
	lz_coder *coder = coder_ptr;
	const bool eof = (action == XR_FINISH);

	while (true) {
		const size_t dict_start = coder->dict.pos;
		const size_t out_avail = out_size - *out_pos;
		size_t room = coder->dict.size - coder->dict.pos;
		if (room > out_avail)
			room = out_avail;

		coder->dict.limit = coder->dict.pos + room;

		const xr_ret ret = coder->lz.code(coder->lz.coder, &coder->dict,
				in, in_pos, in_size, eof);

		const size_t copy_size = coder->dict.pos - dict_start;
		if (copy_size > 0) {
			memcpy(out + *out_pos, coder->dict.buf + dict_start,
					copy_size);
			*out_pos += copy_size;
		}

		if (coder->dict.pos == coder->dict.size)
			coder->dict.pos = 0;

		if (ret != XR_OK)
			return ret;

		if (*out_pos == out_size)
			return XR_OK;

		/* If nothing was produced and no input consumed, we need more
		 * input from the caller. */
		if (copy_size == 0)
			return XR_OK;
	}
}

static void lz_decoder_end(void *coder_ptr)
{
	lz_coder *coder = coder_ptr;
	free(coder->dict.buf);
	if (coder->lz.end != NULL)
		coder->lz.end(coder->lz.coder);
	else
		free(coder->lz.coder);
	free(coder);
}

uint64_t xr_lz_decoder_memusage(uint64_t dict_size)
{
	return sizeof(lz_coder) + dict_size;
}

xr_ret xr_lz_decoder_init(xr_next_coder *next, const xr_filter *filters,
		xr_ret (*lz_init)(xr_lz_decoder *lz, xr_lz_options *lz_options,
			const void *options))
{
	lz_coder *coder = next->coder;

	if (coder == NULL || next->code != &lz_decode) {
		coder = calloc(1, sizeof(lz_coder));
		if (coder == NULL)
			return XR_MEM_ERROR;
		next->coder = coder;
		next->code = &lz_decode;
		next->end = &lz_decoder_end;
	}

	xr_lz_options lz_options;
	memset(&lz_options, 0, sizeof(lz_options));
	const xr_ret ret = lz_init(&coder->lz, &lz_options, filters[0].options);
	if (ret != XR_OK)
		return ret;

	if (lz_options.dict_size < 4096)
		lz_options.dict_size = 4096;
	lz_options.dict_size = (lz_options.dict_size + 15) & ~(size_t)15;

	if (coder->dict.buf == NULL || coder->dict.size != lz_options.dict_size) {
		free(coder->dict.buf);
		coder->dict.buf = malloc(lz_options.dict_size);
		if (coder->dict.buf == NULL) {
			coder->dict.size = 0;
			return XR_MEM_ERROR;
		}
		coder->dict.size = lz_options.dict_size;
	}

	xr_dict_reset(&coder->dict);

	if (lz_options.preset_dict != NULL && lz_options.preset_dict_size > 0) {
		size_t copy = lz_options.preset_dict_size;
		if (copy > lz_options.dict_size)
			copy = lz_options.dict_size;
		memcpy(coder->dict.buf, lz_options.preset_dict
				+ lz_options.preset_dict_size - copy, copy);
		coder->dict.pos = copy;
		coder->dict.full = copy;
	}

	return XR_OK;
}

