						ret = rc.code == 0
							? XR_STREAM_END
							: XR_DATA_ERROR;
						goto out;
					}
				}
			}

			if (!xr_dict_is_distance_valid(dict, rep0)) {
				ret = XR_DATA_ERROR;
				goto out;
			}
		} else {
			rc_update_1(coder->is_rep[state]);

			if (!xr_dict_is_distance_valid(dict, rep0)) {
				ret = XR_DATA_ERROR;
				goto out;
			}

