				rc_update_0(coder->is_rep0[state]);
				rc_if_0(coder->is_rep0_long[state][pos_state]) {
					rc_update_0(coder->is_rep0_long[state][pos_state]);
					update_short_rep(&state);
					xr_dict_put(dict, xr_dict_get(dict, rep0));
					continue;
				}
				rc_update_1(coder->is_rep0_long[state][pos_state]);
			} else {
				rc_update_1(coder->is_rep0[state]);
				uint32_t bit;
				rc_bit_plain(coder->is_rep1[state], bit);
				if (bit == 0) {
					const uint32_t d = rep1;
					rep1 = rep0;
					rep0 = d;
				} else {
					rc_bit_plain(coder->is_rep2[state], bit);
					if (bit == 0) {
						const uint32_t d = rep2;
						rep2 = rep1;
						rep1 = rep0;
						rep0 = d;
					} else {
						const uint32_t d = rep3;
						rep3 = rep2;
						rep2 = rep1;
						rep1 = rep0;
						rep0 = d;
					}
				}
			}

			/* Repeated-match length */
			{
				len_decoder *const ld = &coder->rep_len_dec;
				rc_if_0(ld->choice) {
					rc_update_0(ld->choice);
					symbol = 1;
					do {
						rc_bit(ld->low[pos_state][symbol], , );
					} while (symbol < LEN_LOW_SYMBOLS);
					len = symbol - LEN_LOW_SYMBOLS
							+ MATCH_LEN_MIN;
				} else {
					rc_update_1(ld->choice);
					rc_if_0(ld->choice2) {
						rc_update_0(ld->choice2);
						symbol = 1;
						do {
							rc_bit(ld->mid[pos_state][symbol], , );
						} while (symbol < LEN_MID_SYMBOLS);
						len = symbol - LEN_MID_SYMBOLS
								+ MATCH_LEN_MIN
								+ LEN_LOW_SYMBOLS;
					} else {
						rc_update_1(ld->choice2);
						symbol = 1;
						do {
							rc_bit(ld->high[symbol], , );
						} while (symbol < LEN_HIGH_SYMBOLS);
						len = symbol - LEN_HIGH_SYMBOLS
								+ MATCH_LEN_MIN
								+ LEN_LOW_SYMBOLS
								+ LEN_MID_SYMBOLS;
					}
				}
			}

			update_long_rep(&state);
		}

