	coder->position += dict->pos - dict_start;
	coder->state = state;
	coder->rep0 = rep0;
	coder->rep1 = rep1;
	coder->rep2 = rep2;
	coder->rep3 = rep3;
	if (coder->uncompressed_size != XR_VLI_UNKNOWN)
		coder->uncompressed_size -= dict->pos - dict_start;

	rc_from_local(coder->rc, *in_pos);
	dict->limit = dict_limit_orig;

	if (ret == XR_OK && coder->uncompressed_size == 0)
		ret = XR_STREAM_END;

	return ret;
}

