			ret = decode_real(coder, dict, coder->temp.buf,
					&tpos, tlimit);
			if (tpos > tsize)
				return XR_DATA_ERROR;

			if (tpos >= coder->temp.size) {
				*in_pos += tpos - coder->temp.size;
				coder->temp.size = 0;
			} else {
				coder->temp.size = tsize - tpos;
				memmove(coder->temp.buf, coder->temp.buf + tpos,
						coder->temp.size);
				*in_pos += copy;
				return ret;
			}

			if (ret != XR_OK)
				return ret;
			if (dict->pos == dict->limit)
				return XR_OK;
		}

		size_t avail = in_size - *in_pos;

		if (avail >= LZMA_IN_REQUIRED) {
			ret = decode_real(coder, dict, in, in_pos,
					in_size - LZMA_IN_REQUIRED);
			if (ret != XR_OK)
				return ret;
			if (dict->pos == dict->limit)
				return XR_OK;
			avail = in_size - *in_pos;
