	bool stream_ended;

	uint64_t position;
	uint32_t pending_len;

	struct {
		size_t size;
		uint8_t buf[TEMP_BUF_SIZE];
	} temp;

	uint32_t dict_size;
	const uint8_t *preset_dict;
	size_t preset_dict_size;
