static void lzma_dec_reset_state(lzma_dec *coder)
{
	coder->state = 0;
	coder->rep0 = 0;
	coder->rep1 = 0;
	coder->rep2 = 0;
	coder->rep3 = 0;
	coder->position = 0;
	coder->pending_len = 0;

	for (size_t i = 0; i < STATES; ++i) {
		for (size_t j = 0; j < POS_STATES_MAX; ++j) {
			coder->is_match[i][j] = RC_BIT_MODEL_TOTAL / 2;
			coder->is_rep0_long[i][j] = RC_BIT_MODEL_TOTAL / 2;
		}
		coder->is_rep[i] = RC_BIT_MODEL_TOTAL / 2;
		coder->is_rep0[i] = RC_BIT_MODEL_TOTAL / 2;
		coder->is_rep1[i] = RC_BIT_MODEL_TOTAL / 2;
		coder->is_rep2[i] = RC_BIT_MODEL_TOTAL / 2;
	}
	for (size_t i = 0; i < DIST_STATES; ++i)
		for (size_t j = 0; j < DIST_SLOTS; ++j)
			coder->dist_slot[i][j] = RC_BIT_MODEL_TOTAL / 2;
	for (size_t i = 0; i < FULL_DISTANCES - DIST_MODEL_END; ++i)
		coder->pos_special[i] = RC_BIT_MODEL_TOTAL / 2;
	for (size_t i = 0; i < ALIGN_SIZE; ++i)
		coder->pos_align[i] = RC_BIT_MODEL_TOTAL / 2;

	len_decoder_reset(&coder->match_len_dec);
	len_decoder_reset(&coder->rep_len_dec);

	for (size_t i = 0; i < LITERAL_CODERS_MAX * LITERAL_CODER_SIZE; ++i)
		coder->literal[i] = RC_BIT_MODEL_TOTAL / 2;

	rc_reset(&coder->rc);
	coder->temp.size = 0;
	coder->stream_ended = false;
}

