/* Decodes symbols while the symbol start index is <= in_limit, which
 * guarantees that LZMA_IN_REQUIRED bytes can be read safely. */
static xr_ret decode_real(lzma_dec *restrict coder, xr_dict *restrict dict,
		const uint8_t *restrict in, size_t *restrict in_pos,
		size_t in_limit)
{
	uint32_t state = coder->state;
	uint32_t rep0 = coder->rep0;
	uint32_t rep1 = coder->rep1;
	uint32_t rep2 = coder->rep2;
	uint32_t rep3 = coder->rep3;

	const uint32_t pos_mask = coder->pos_mask;
	const uint32_t literal_pos_mask = coder->literal_pos_mask;
	const uint32_t lc = coder->lc;

	const size_t dict_limit_orig = dict->limit;
	const size_t dict_start = dict->pos;

	if (coder->uncompressed_size != XR_VLI_UNKNOWN) {
		const uint64_t room = (uint64_t)(dict->limit - dict->pos);
		if (room > coder->uncompressed_size)
			dict->limit = dict->pos
					+ (size_t)coder->uncompressed_size;
	}

	rc_to_local(coder->rc, *in_pos);

	xr_ret ret = XR_OK;
	uint32_t symbol;
	uint32_t len = 0;
	probability *probs;

	/* Finish a match copy that was interrupted by a full output buffer. */
	if (coder->pending_len > 0) {
		uint32_t left = coder->pending_len;
		xr_dict_repeat(dict, rep0, &left);
		coder->pending_len = left;
		if (left > 0)
			goto out;
	}

	while (dict->pos < dict->limit && rc_in_pos <= in_limit) {
		const uint64_t total_pos = coder->position
				+ (uint64_t)(dict->pos - dict_start);
		const uint32_t pos_state = (uint32_t)total_pos & pos_mask;

		rc_if_0(coder->is_match[state][pos_state]) {
			rc_update_0(coder->is_match[state][pos_state]);

			const uint8_t prev_byte = dict->full > 0
					? xr_dict_get(dict, 0) : 0;
			probs = coder->literal + LITERAL_CODER_SIZE
					* ((((uint32_t)total_pos
						& literal_pos_mask) << lc)
					+ ((uint32_t)prev_byte >> (8 - lc)));

			symbol = 1;
			if (is_literal_state(state)) {
				do {
					rc_bit(probs[symbol], , );
				} while (symbol < 0x100);
			} else {
				uint32_t match_byte =
						(uint32_t)xr_dict_get(dict, rep0);
				uint32_t offset = 0x100;
				match_byte <<= 1;
				do {
					const uint32_t match_bit =
							match_byte & offset;
					const uint32_t idx =
							offset + match_bit + symbol;
					rc_bit(probs[idx],
						offset &= ~match_bit,
						offset &= match_bit);
					match_byte <<= 1;
				} while (symbol < 0x100);
			}

			xr_dict_put(dict, (uint8_t)symbol);
			update_literal(&state);
			continue;
		}

		rc_update_1(coder->is_match[state][pos_state]);

		rc_if_0(coder->is_rep[state]) {
			rc_update_0(coder->is_rep[state]);

			rep3 = rep2;
			rep2 = rep1;
			rep1 = rep0;

			LEN_DECODE(&coder->match_len_dec, len);
			update_match(&state);

			probs = coder->dist_slot[get_dist_state(len)];
			symbol = 1;
			do {
				rc_bit(probs[symbol], , );
			} while (symbol < DIST_SLOTS);
			symbol -= DIST_SLOTS;

			if (symbol < DIST_MODEL_START) {
				rep0 = symbol;
			} else {
				const uint32_t limit = (symbol >> 1) - 1;
				rep0 = (2 | (symbol & 1)) << limit;

				if (symbol < DIST_MODEL_END) {
					probs = coder->pos_special + rep0
							- symbol - 1;
					rc_bittree_reverse(probs, rep0, limit);
				} else {
					uint32_t direct = 0;
					rc_direct(direct, limit - ALIGN_BITS);
					rep0 += direct << ALIGN_BITS;
					rc_bittree_reverse(coder->pos_align,
							rep0, ALIGN_BITS);

					if (rep0 == UINT32_MAX) {
						if (!coder->allow_eopm) {
							ret = XR_DATA_ERROR;
							goto out;
						}
						rc_normalize();
						coder->stream_ended = true;
						ret = rc.code == 0
							? XR_STREAM_END
							: XR_DATA_ERROR;
						goto out;
					}
				}
			}

			if (!xr_dict_is_distance_valid(dict, rep0)) {
				ret = XR_DATA_ERROR;
				goto out;
			}
		} else {
			rc_update_1(coder->is_rep[state]);

			if (!xr_dict_is_distance_valid(dict, rep0)) {
				ret = XR_DATA_ERROR;
				goto out;
			}

			rc_if_0(coder->is_rep0[state]) {
				rc_update_0(coder->is_rep0[state]);
				rc_if_0(coder->is_rep0_long[state][pos_state]) {
					rc_update_0(coder->is_rep0_long[state][pos_state]);
					update_short_rep(&state);
					xr_dict_put(dict, xr_dict_get(dict, rep0));
					continue;
				}
				rc_update_1(coder->is_rep0_long[state][pos_state]);
			} else {
				rc_update_1(coder->is_rep0[state]);
				uint32_t bit;
				rc_bit_plain(coder->is_rep1[state], bit);
				if (bit == 0) {
					const uint32_t d = rep1;
					rep1 = rep0;
					rep0 = d;
				} else {
					rc_bit_plain(coder->is_rep2[state], bit);
					if (bit == 0) {
						const uint32_t d = rep2;
						rep2 = rep1;
						rep1 = rep0;
						rep0 = d;
					} else {
						const uint32_t d = rep3;
						rep3 = rep2;
						rep2 = rep1;
						rep1 = rep0;
						rep0 = d;
					}
				}
			}

			LEN_DECODE(&coder->rep_len_dec, len);
			update_long_rep(&state);
		}

		{
			uint32_t left = len;
			xr_dict_repeat(dict, rep0, &left);
			if (left > 0) {
				coder->pending_len = left;
				goto out;
			}
		}
	}

out:
	coder->position += (uint64_t)(dict->pos - dict_start);
	coder->state = state;
	coder->rep0 = rep0;
	coder->rep1 = rep1;
	coder->rep2 = rep2;
	coder->rep3 = rep3;
	if (coder->uncompressed_size != XR_VLI_UNKNOWN)
		coder->uncompressed_size -= (uint64_t)(dict->pos - dict_start);

	rc_from_local(coder->rc, *in_pos);
	dict->limit = dict_limit_orig;

	if (ret == XR_OK && coder->uncompressed_size == 0
			&& coder->pending_len == 0)
		ret = XR_STREAM_END;

	return ret;
}

static xr_ret lzma_decode(void *coder_ptr, xr_dict *restrict dict,
		const uint8_t *restrict in, size_t *restrict in_pos,
		size_t in_size, bool eof)
{
	lzma_dec *coder = coder_ptr;

	if (coder->rc.init_bytes_left > 0) {
		if (!rc_read_init(&coder->rc, in, in_pos, in_size))
			return XR_OK;
	}

	xr_ret ret = XR_OK;

	while (true) {
		if (coder->temp.size > 0) {
			const size_t avail = in_size - *in_pos;
			size_t space = TEMP_FILL_MAX - coder->temp.size;
			const size_t copy = avail < space ? avail : space;
			memcpy(coder->temp.buf + coder->temp.size,
					in + *in_pos, copy);
			const size_t tsize = coder->temp.size + copy;

			size_t tlimit;
			if (tsize >= LZMA_IN_REQUIRED) {
				tlimit = tsize - LZMA_IN_REQUIRED;
			} else if (eof && copy == avail) {
				memset(coder->temp.buf + tsize, 0,
						LZMA_IN_REQUIRED);
				tlimit = tsize;
			} else {
				coder->temp.size = tsize;
				*in_pos += copy;
				return XR_OK;
			}

			size_t tpos = 0;
			ret = decode_real(coder, dict, coder->temp.buf,
					&tpos, tlimit);
			if (tpos > tsize)
				return XR_DATA_ERROR;

			if (tpos >= coder->temp.size) {
				*in_pos += tpos - coder->temp.size;
				coder->temp.size = 0;
			} else {
				coder->temp.size = tsize - tpos;
				memmove(coder->temp.buf, coder->temp.buf + tpos,
						coder->temp.size);
				*in_pos += copy;
				return ret;
			}

			if (ret != XR_OK)
				return ret;
			if (dict->pos == dict->limit)
				return XR_OK;
		}

		size_t avail = in_size - *in_pos;

		if (avail >= LZMA_IN_REQUIRED) {
			ret = decode_real(coder, dict, in, in_pos,
					in_size - LZMA_IN_REQUIRED);
			if (ret != XR_OK)
				return ret;
			if (dict->pos == dict->limit)
				return XR_OK;
			avail = in_size - *in_pos;
		}

		if (!eof) {
			if (avail > 0) {
				memcpy(coder->temp.buf, in + *in_pos, avail);
				coder->temp.size = avail;
				*in_pos = in_size;
			}
			return XR_OK;
		}

		/* Final bytes: decode from a zero-padded copy. */
		memcpy(coder->temp.buf, in + *in_pos, avail);
		memset(coder->temp.buf + avail, 0, LZMA_IN_REQUIRED);
		size_t tpos = 0;
		ret = decode_real(coder, dict, coder->temp.buf, &tpos, avail);
		if (tpos > avail)
			return XR_DATA_ERROR;
		*in_pos += tpos;
		return ret;
	}
}

static void lzma_dec_set_uncompressed(void *coder_ptr,
		xr_vli uncompressed_size, bool allow_eopm)
{
	lzma_dec *coder = coder_ptr;
	coder->uncompressed_size = uncompressed_size;
	coder->allow_eopm = allow_eopm;
}

static void lzma_dec_reset(void *coder_ptr, const void *opt)
{
	lzma_dec *coder = coder_ptr;
	const xr_options_lzma *options = opt;
	coder->lc = options->lc;
	coder->literal_pos_mask = (UINT32_C(1) << options->lp) - 1;
	coder->pos_mask = (UINT32_C(1) << options->pb) - 1;
	lzma_dec_reset_state(coder);
}

/* Shared by lzma1 and lzma2 initialisation. */
xr_ret xr_lzma_decoder_create(xr_lz_decoder *lz, xr_lz_options *lz_options,
		const xr_options_lzma *options)
{
	if (lz->coder == NULL) {
		lz->coder = malloc(sizeof(lzma_dec));
		if (lz->coder == NULL)
			return XR_MEM_ERROR;
		lz->code = &lzma_decode;
		lz->reset = &lzma_dec_reset;
		lz->set_uncompressed = &lzma_dec_set_uncompressed;
		lz->end = NULL;
	}

	lz_options->dict_size = options->dict_size;
	lz_options->preset_dict = options->preset_dict;
	lz_options->preset_dict_size = options->preset_dict_size;

	lzma_dec *coder = lz->coder;
	memset(coder, 0, sizeof(*coder));
	coder->uncompressed_size = XR_VLI_UNKNOWN;
	coder->allow_eopm = true;
	return XR_OK;
}

bool xr_lzma_lclppb_valid(const xr_options_lzma *options)
{
	return options->lc <= XR_LCLP_MAX && options->lp <= XR_LCLP_MAX
			&& options->lc + options->lp <= XR_LCLP_MAX
			&& options->pb <= XR_PB_MAX;
}

static xr_ret lzma_decoder_init_lz(xr_lz_decoder *lz, xr_lz_options *lz_options,
		const void *opt)
{
	const xr_options_lzma *options = opt;
	if (!xr_lzma_lclppb_valid(options))
		return XR_PROG_ERROR;

	const xr_ret ret = xr_lzma_decoder_create(lz, lz_options, options);
	if (ret != XR_OK)
		return ret;

	lz->reset(lz->coder, options);
	lz->set_uncompressed(lz->coder,
			options->ext_flags != 0 ? XR_VLI_UNKNOWN
				: XR_VLI_UNKNOWN, true);
	return XR_OK;
}

xr_ret xr_lzma_decoder_init(xr_next_coder *next, const xr_filter *filters)
{
	return xr_lz_decoder_init(next, filters, &lzma_decoder_init_lz);
}

uint64_t xr_lzma_decoder_memusage_nocheck(const void *opt)
{
	const xr_options_lzma *options = opt;
	return xr_lz_decoder_memusage(options->dict_size) + sizeof(lzma_dec);
}

uint64_t xr_lzma_decoder_memusage(const void *opt)
{
	const xr_options_lzma *options = opt;
	if (!xr_lzma_lclppb_valid(options))
		return UINT64_MAX;
	return xr_lzma_decoder_memusage_nocheck(opt);
}

/* Used by the LZMA2 decoder, which owns the lzma_dec directly. */
void xr_lzma_decoder_uncompressed(void *coder, xr_vli uncompressed_size,
		bool allow_eopm)
{
	lzma_dec_set_uncompressed(coder, uncompressed_size, allow_eopm);
}

void xr_lzma_decoder_reset_props(void *coder_ptr, uint32_t lc, uint32_t lp,
		uint32_t pb)
{
	lzma_dec *coder = coder_ptr;
	coder->lc = lc;
	coder->literal_pos_mask = (UINT32_C(1) << lp) - 1;
	coder->pos_mask = (UINT32_C(1) << pb) - 1;
	lzma_dec_reset_state(coder);
}

void xr_lzma_decoder_reset_rc(void *coder_ptr)
{
	lzma_dec *coder = coder_ptr;
	rc_reset(&coder->rc);
	coder->temp.size = 0;
	coder->pending_len = 0;
}

void xr_lzma_decoder_reset_lzma_state(void *coder_ptr)
{
	lzma_dec *coder = coder_ptr;
	const uint32_t lc = coder->lc;
	const uint32_t lpm = coder->literal_pos_mask;
	const uint32_t pm = coder->pos_mask;
	lzma_dec_reset_state(coder);
	coder->lc = lc;
	coder->literal_pos_mask = lpm;
	coder->pos_mask = pm;
}

bool xr_lzma_decoder_is_finished(const void *coder_ptr)
{
	const lzma_dec *coder = coder_ptr;
	return rc_is_finished(&coder->rc) && coder->pending_len == 0;
}

xr_ret xr_lzma_dec_code(void *coder, xr_dict *dict, const uint8_t *in,
		size_t *in_pos, size_t in_size, bool eof)
{
	return lzma_decode(coder, dict, in, in_pos, in_size, eof);
}

size_t xr_lzma_dec_size(void)
{
	return sizeof(lzma_dec);
}

