#include "lzma_common.h"
#include "lz_decoder.h"
#include "range_decoder.h"
#include "filter.h"

#define TEMP_FILL_MAX (2 * LZMA_IN_REQUIRED)
#define TEMP_BUF_SIZE (3 * LZMA_IN_REQUIRED)

typedef struct {
	probability choice;
	probability choice2;
	probability low[POS_STATES_MAX][LEN_LOW_SYMBOLS];
	probability mid[POS_STATES_MAX][LEN_MID_SYMBOLS];
	probability high[LEN_HIGH_SYMBOLS];
} len_decoder;

typedef struct {
	uint32_t state;
	uint32_t rep0, rep1, rep2, rep3;

	probability is_match[STATES][POS_STATES_MAX];
	probability is_rep[STATES];
	probability is_rep0[STATES];
	probability is_rep1[STATES];
	probability is_rep2[STATES];
	probability is_rep0_long[STATES][POS_STATES_MAX];
	probability dist_slot[DIST_STATES][DIST_SLOTS];
	probability pos_special[FULL_DISTANCES - DIST_MODEL_END];
	probability pos_align[ALIGN_SIZE];

	len_decoder match_len_dec;
	len_decoder rep_len_dec;

	probability literal[LITERAL_CODERS_MAX * LITERAL_CODER_SIZE];

	uint32_t lc;
	uint32_t literal_pos_mask;
	uint32_t pos_mask;

	xr_range_decoder rc;

	xr_vli uncompressed_size;
	bool allow_eopm;
	bool stream_ended;

	/* Total number of bytes produced, used for the position state. */
	uint64_t position;

	struct {
		size_t size;
		uint8_t buf[TEMP_BUF_SIZE];
	} temp;

	uint32_t dict_size;
	const uint8_t *preset_dict;
	size_t preset_dict_size;
} lzma_dec;

static void len_decoder_reset(len_decoder *ld)
{
	ld->choice = RC_BIT_MODEL_TOTAL / 2;
	ld->choice2 = RC_BIT_MODEL_TOTAL / 2;
	for (size_t i = 0; i < POS_STATES_MAX; ++i) {
		for (size_t j = 0; j < LEN_LOW_SYMBOLS; ++j)
			ld->low[i][j] = RC_BIT_MODEL_TOTAL / 2;
		for (size_t j = 0; j < LEN_MID_SYMBOLS; ++j)
			ld->mid[i][j] = RC_BIT_MODEL_TOTAL / 2;
	}
	for (size_t i = 0; i < LEN_HIGH_SYMBOLS; ++i)
		ld->high[i] = RC_BIT_MODEL_TOTAL / 2;
}

static void lzma_dec_reset_state(lzma_dec *coder)
{
	coder->state = 0;
	coder->rep0 = 0;
	coder->rep1 = 0;
	coder->rep2 = 0;
	coder->rep3 = 0;
	coder->position = 0;

	probability *p = (probability *)&coder->is_match[0][0];
	probability *const end = (probability *)&coder->pos_align[ALIGN_SIZE];
	while (p != end)
		*p++ = RC_BIT_MODEL_TOTAL / 2;

	len_decoder_reset(&coder->match_len_dec);
	len_decoder_reset(&coder->rep_len_dec);

	const size_t n = (size_t)LITERAL_CODER_SIZE
			<< (coder->lc + (coder->literal_pos_mask
				? 0 : 0));
	(void)n;
	for (size_t i = 0; i < LITERAL_CODERS_MAX * LITERAL_CODER_SIZE; ++i)
		coder->literal[i] = RC_BIT_MODEL_TOTAL / 2;

	rc_reset(&coder->rc);
	coder->temp.size = 0;
	coder->stream_ended = false;
}

/* Decodes symbols while at least LZMA_IN_REQUIRED bytes are guaranteed to be
 * readable, i.e. while the symbol start index is <= in_limit. */
static xr_ret decode_real(lzma_dec *restrict coder, xr_dict *restrict dict,
		const uint8_t *restrict in, size_t *restrict in_pos,
		size_t in_limit)
{
	uint32_t state = coder->state;
	uint32_t rep0 = coder->rep0;
	uint32_t rep1 = coder->rep1;
	uint32_t rep2 = coder->rep2;
	uint32_t rep3 = coder->rep3;

	const uint32_t pos_mask = coder->pos_mask;
	const uint32_t literal_pos_mask = coder->literal_pos_mask;
	const uint32_t lc = coder->lc;

	const size_t dict_limit_orig = dict->limit;
	const size_t dict_start = dict->pos;

	if (coder->uncompressed_size != XR_VLI_UNKNOWN) {
		const uint64_t room = (uint64_t)(dict->limit - dict->pos);
		if (room > coder->uncompressed_size)
			dict->limit = dict->pos
					+ (size_t)coder->uncompressed_size;
	}

	rc_to_local(coder->rc, *in_pos);

	xr_ret ret = XR_OK;
	uint32_t symbol;
	uint32_t len = 0;
	probability *probs;

	while (dict->pos < dict->limit && rc_in_pos <= in_limit) {
		const uint32_t pos_state =
				(uint32_t)(coder->position + (dict->pos - dict_start))
				& pos_mask;

		rc_if_0(coder->is_match[state][pos_state]) {
			rc_update_0(coder->is_match[state][pos_state]);

			/* Literal */
			const uint8_t prev_byte = dict->full > 0
					? xr_dict_get(dict, 0) : 0;
			probs = coder->literal + LITERAL_CODER_SIZE
					* ((((uint32_t)(coder->position
						+ (dict->pos - dict_start))
						& literal_pos_mask) << lc)
					+ ((uint32_t)prev_byte >> (8 - lc)));

			symbol = 1;
			if (is_literal_state(state)) {
				do {
					rc_bit(probs[symbol], , );
				} while (symbol < 0x100);
			} else {
				uint32_t match_byte =
						(uint32_t)xr_dict_get(dict, rep0);
				uint32_t offset = 0x100;
				match_byte <<= 1;
				do {
					const uint32_t match_bit =
							match_byte & offset;
					const uint32_t idx =
							offset + match_bit + symbol;
					rc_bit(probs[idx],
						offset &= ~match_bit,
						offset &= match_bit);
					match_byte <<= 1;
				} while (symbol < 0x100);
			}

			xr_dict_put(dict, (uint8_t)symbol);
			update_literal(&state);
			continue;
		}

		rc_update_1(coder->is_match[state][pos_state]);

		rc_if_0(coder->is_rep[state]) {
			rc_update_0(coder->is_rep[state]);

			/* Simple match: shift the rep distances. */
			rep3 = rep2;
			rep2 = rep1;
			rep1 = rep0;

			/* Length */
			{
				len_decoder *const ld = &coder->match_len_dec;
				rc_if_0(ld->choice) {
					rc_update_0(ld->choice);
					symbol = 1;
					do {
						rc_bit(ld->low[pos_state][symbol], , );
					} while (symbol < LEN_LOW_SYMBOLS);
					len = symbol - LEN_LOW_SYMBOLS
							+ MATCH_LEN_MIN;
				} else {
					rc_update_1(ld->choice);
					rc_if_0(ld->choice2) {
						rc_update_0(ld->choice2);
						symbol = 1;
						do {
							rc_bit(ld->mid[pos_state][symbol], , );
						} while (symbol < LEN_MID_SYMBOLS);
						len = symbol - LEN_MID_SYMBOLS
								+ MATCH_LEN_MIN
								+ LEN_LOW_SYMBOLS;
					} else {
						rc_update_1(ld->choice2);
						symbol = 1;
						do {
							rc_bit(ld->high[symbol], , );
						} while (symbol < LEN_HIGH_SYMBOLS);
						len = symbol - LEN_HIGH_SYMBOLS
								+ MATCH_LEN_MIN
								+ LEN_LOW_SYMBOLS
								+ LEN_MID_SYMBOLS;
					}
				}
			}

			update_match(&state);

			/* Distance */
			probs = coder->dist_slot[get_dist_state(len)];
			symbol = 1;
			do {
				rc_bit(probs[symbol], , );
			} while (symbol < DIST_SLOTS);
			symbol -= DIST_SLOTS;

			if (symbol < DIST_MODEL_START) {
				rep0 = symbol;
			} else {
				const uint32_t limit = (symbol >> 1) - 1;
				rep0 = (2 | (symbol & 1)) << limit;

				if (symbol < DIST_MODEL_END) {
					probs = coder->pos_special + rep0
							- symbol - 1;
					rc_bittree_reverse(probs, rep0, limit);
				} else {
					uint32_t direct = 0;
					rc_direct(direct, limit - ALIGN_BITS);
					rep0 += direct << ALIGN_BITS;
					rc_bittree_reverse(coder->pos_align,
							rep0, ALIGN_BITS);

					if (rep0 == UINT32_MAX) {
						/* End of payload marker */
						if (!coder->allow_eopm) {
							ret = XR_DATA_ERROR;
							goto out;
						}
						rc_normalize();
						coder->stream_ended = true;
						ret = rc.code == 0
							? XR_STREAM_END
							: XR_DATA_ERROR;
						goto out;
					}
				}
			}

			if (!xr_dict_is_distance_valid(dict, rep0)) {
				ret = XR_DATA_ERROR;
				goto out;
			}
		} else {
			rc_update_1(coder->is_rep[state]);

			if (!xr_dict_is_distance_valid(dict, rep0)) {
				ret = XR_DATA_ERROR;
				goto out;
			}

			rc_if_0(coder->is_rep0[state]) {
				rc_update_0(coder->is_rep0[state]);
				rc_if_0(coder->is_rep0_long[state][pos_state]) {
					rc_update_0(coder->is_rep0_long[state][pos_state]);
					update_short_rep(&state);
					xr_dict_put(dict, xr_dict_get(dict, rep0));
					continue;
				}
				rc_update_1(coder->is_rep0_long[state][pos_state]);
			} else {
				rc_update_1(coder->is_rep0[state]);
				uint32_t bit;
				rc_bit_plain(coder->is_rep1[state], bit);
				if (bit == 0) {
					const uint32_t d = rep1;
					rep1 = rep0;
					rep0 = d;
				} else {
					rc_bit_plain(coder->is_rep2[state], bit);
					if (bit == 0) {
						const uint32_t d = rep2;
						rep2 = rep1;
						rep1 = rep0;
						rep0 = d;
					} else {
						const uint32_t d = rep3;
						rep3 = rep2;
						rep2 = rep1;
						rep1 = rep0;
						rep0 = d;
					}
				}
			}

			/* Repeated-match length */
			{
				len_decoder *const ld = &coder->rep_len_dec;
				rc_if_0(ld->choice) {
					rc_update_0(ld->choice);
					symbol = 1;
					do {
						rc_bit(ld->low[pos_state][symbol], , );
					} while (symbol < LEN_LOW_SYMBOLS);
					len = symbol - LEN_LOW_SYMBOLS
							+ MATCH_LEN_MIN;
				} else {
					rc_update_1(ld->choice);
					rc_if_0(ld->choice2) {
						rc_update_0(ld->choice2);
						symbol = 1;
						do {
							rc_bit(ld->mid[pos_state][symbol], , );
						} while (symbol < LEN_MID_SYMBOLS);
						len = symbol - LEN_MID_SYMBOLS
								+ MATCH_LEN_MIN
								+ LEN_LOW_SYMBOLS;
					} else {
						rc_update_1(ld->choice2);
						symbol = 1;
						do {
							rc_bit(ld->high[symbol], , );
						} while (symbol < LEN_HIGH_SYMBOLS);
						len = symbol - LEN_HIGH_SYMBOLS
								+ MATCH_LEN_MIN
								+ LEN_LOW_SYMBOLS
								+ LEN_MID_SYMBOLS;
					}
				}
			}

			update_long_rep(&state);
		}

		/* Copy the match into the dictionary. */
		{
			uint32_t left = len;
			xr_dict_repeat(dict, rep0, &left);
			if (left > 0) {
				/* Ran out of dictionary/output room; the caller
				 * flushes and we continue on the next call. */
				coder->position += dict->pos - dict_start;
				coder->state = state;
				coder->rep0 = rep0;
				coder->rep1 = rep1;
				coder->rep2 = rep2;
				coder->rep3 = rep3;
				if (coder->uncompressed_size != XR_VLI_UNKNOWN)
					coder->uncompressed_size -=
							dict->pos - dict_start;
				coder->pending_len = left;
				rc_from_local(coder->rc, *in_pos);
				dict->limit = dict_limit_orig;
				return XR_OK;
			}
		}
	}

out:
	coder->position += dict->pos - dict_start;
	coder->state = state;
	coder->rep0 = rep0;
	coder->rep1 = rep1;
	coder->rep2 = rep2;
	coder->rep3 = rep3;
	if (coder->uncompressed_size != XR_VLI_UNKNOWN)
		coder->uncompressed_size -= dict->pos - dict_start;

	rc_from_local(coder->rc, *in_pos);
	dict->limit = dict_limit_orig;

	if (ret == XR_OK && coder->uncompressed_size == 0)
		ret = XR_STREAM_END;

	return ret;
}

