	coder->position = 0;
	coder->pending_len = 0;
""", """	coder->rep3 = 0;
	coder->pending_len = 0;
""")
s = s.replace("""		const uint64_t total_pos = coder->position
				+ (uint64_t)(dict->pos - dict_start);
		const uint32_t pos_state = (uint32_t)total_pos & pos_mask;
""", """		const uint32_t total_pos = (uint32_t)dict->pos;
		const uint32_t pos_state = total_pos & pos_mask;
""")
s = s.replace("""			probs = coder->literal + LITERAL_CODER_SIZE
					* ((((uint32_t)total_pos
						& literal_pos_mask) << lc)
					+ ((uint32_t)prev_byte >> (8 - lc)));
""", """			probs = coder->literal + LITERAL_CODER_SIZE
					* (((total_pos & literal_pos_mask) << lc)
					+ ((uint32_t)prev_byte >> (8 - lc)));
""")
s = s.replace("""out:
	coder->position += (uint64_t)(dict->pos - dict_start);
	coder->state = state;""", """out:
	coder->state = state;""")
open(p,'w').write(s)
print("ok")
