/* ------------------------------------------------------------------ */
/* Interface used by the LZMA2 chunk layer and by the LZMA1 filter      */
/* ------------------------------------------------------------------ */

size_t xr_lzma_dec_size(void)
{
	return sizeof(lzma_dec);
}

void xr_lzma_dec_init(void *coder_ptr)
{
	lzma_dec *coder = coder_ptr;
	memset(coder, 0, sizeof(*coder));
	coder->uncompressed_size = XR_VLI_UNKNOWN;
	coder->allow_eopm = true;
	coder->lc = 3;
	coder->literal_pos_mask = 0;
	coder->pos_mask = 3;
}

bool xr_lzma_lclppb_valid(const xr_options_lzma *options)
{
	return options->lc <= XR_LCLP_MAX && options->lp <= XR_LCLP_MAX
			&& options->lc + options->lp <= XR_LCLP_MAX
			&& options->pb <= XR_PB_MAX;
}

bool xr_lzma_lclppb_encode(const xr_options_lzma *options, uint8_t *byte)
{
	if (!xr_lzma_lclppb_valid(options))
		return true;
	*byte = (uint8_t)((options->pb * 5 + options->lp) * 9 + options->lc);
	return false;
}

bool xr_lzma_lclppb_decode(xr_options_lzma *options, uint8_t byte)
{
	if (byte >= (9 * 5 * 5))
		return true;
	options->lc = byte % 9;
	byte /= 9;
	options->lp = byte % 5;
	options->pb = byte / 5;
	return false;
}

bool xr_lzma_dec_set_props_byte(void *coder_ptr, uint8_t props)
{
	xr_options_lzma o;
	memset(&o, 0, sizeof(o));
	if (xr_lzma_lclppb_decode(&o, props))
		return false;
	xr_lzma_dec_set_lclppb(coder_ptr, o.lc, o.lp, o.pb);
	return true;
}

void xr_lzma_dec_set_lclppb(void *coder_ptr, uint32_t lc, uint32_t lp,
		uint32_t pb)
{
	lzma_dec *coder = coder_ptr;
	coder->lc = lc;
	coder->literal_pos_mask = (UINT32_C(1) << lp) - 1;
	coder->pos_mask = (UINT32_C(1) << pb) - 1;
}

void xr_lzma_dec_reset_state(void *coder_ptr)
{
	lzma_dec_reset_state((lzma_dec *)coder_ptr);
}

void xr_lzma_dec_reset_rc(void *coder_ptr)
{
	lzma_dec *coder = coder_ptr;
	rc_reset(&coder->rc);
	coder->temp.size = 0;
	coder->pending_len = 0;
}

void xr_lzma_dec_set_uncompressed(void *coder_ptr, xr_vli size,
		bool allow_eopm)
{
	lzma_dec *coder = coder_ptr;
	coder->uncompressed_size = size;
	coder->allow_eopm = allow_eopm;
}

bool xr_lzma_dec_rc_finished(const void *coder_ptr)
{
	const lzma_dec *coder = coder_ptr;
	return rc_is_finished(&coder->rc) && coder->pending_len == 0
			&& coder->temp.size == 0;
}

xr_ret xr_lzma_dec_code(void *coder, xr_dict *restrict dict,
		const uint8_t *restrict in, size_t *restrict in_pos,
		size_t in_size, bool eof)
{
	return lzma_decode(coder, dict, in, in_pos, in_size, eof);
}

/* ------------------------------------------------------------------ */
/* LZMA1 filter                                                         */
/* ------------------------------------------------------------------ */

static xr_ret lzma1_init_lz(xr_lz_decoder *lz, xr_lz_options *lz_options,
		const void *opt)
{
	const xr_options_lzma *options = opt;
	if (!xr_lzma_lclppb_valid(options))
		return XR_OPTIONS_ERROR;

	if (lz->coder == NULL) {
		lz->coder = malloc(sizeof(lzma_dec));
		if (lz->coder == NULL)
			return XR_MEM_ERROR;
		lz->code = &lzma_decode;
		lz->end = NULL;
		lz->reset = NULL;
		lz->set_uncompressed = NULL;
	}

	xr_lzma_dec_init(lz->coder);
	xr_lzma_dec_set_lclppb(lz->coder, options->lc, options->lp, options->pb);
	lzma_dec_reset_state(lz->coder);

	/* ext_flags bit 0 marks that an uncompressed size is known. */
	if (options->ext_flags & 1) {
		const xr_vli size = ((xr_vli)options->ext_size_high << 32)
				| options->ext_size_low;
		xr_lzma_dec_set_uncompressed(lz->coder, size, true);
	}

	lz_options->dict_size = options->dict_size;
	lz_options->preset_dict = options->preset_dict;
	lz_options->preset_dict_size = options->preset_dict_size;
	return XR_OK;
}

xr_ret xr_lzma_decoder_init(xr_next_coder *next, const xr_filter *filters)
{
	return xr_lz_decoder_init(next, filters, &lzma1_init_lz);
}

uint64_t xr_lzma_decoder_memusage(const void *opt)
{
	const xr_options_lzma *options = opt;
	if (!xr_lzma_lclppb_valid(options))
		return UINT64_MAX;
	return xr_lz_decoder_memusage(options->dict_size) + sizeof(lzma_dec);
}
