#include "lzma_common.h"
#include "lz_decoder.h"
#include "lzma_decoder.h"
#include "filter.h"

typedef enum {
	SEQ_CONTROL,
	SEQ_UNCOMPRESSED_1,
	SEQ_UNCOMPRESSED_2,
	SEQ_COMPRESSED_0,
	SEQ_COMPRESSED_1,
	SEQ_PROPERTIES,
	SEQ_LZMA,
	SEQ_COPY
} lzma2_sequence;

typedef struct {
	lzma2_sequence sequence;
	lzma2_sequence next_sequence;
	void *lzma;
	uint32_t uncompressed_size;
	uint32_t compressed_size;
	bool need_props;
	bool need_dictionary_reset;
} lzma2_dec;

static xr_ret lzma2_decode(void *coder_ptr, xr_dict *restrict dict,
		const uint8_t *restrict in, size_t *restrict in_pos,
		size_t in_size, bool eof)
{
	lzma2_dec *coder = coder_ptr;

	while (*in_pos < in_size || coder->sequence == SEQ_LZMA) {
		switch (coder->sequence) {
		case SEQ_CONTROL: {
			const uint32_t control = in[*in_pos];
			++*in_pos;

			if (control == 0x00)
				return XR_STREAM_END;

			if (control >= 0x80) {
				const uint32_t mode = (control >> 5) & 0x03;

				if (mode == 3) {
					xr_dict_reset(dict);
					coder->need_dictionary_reset = false;
				} else if (coder->need_dictionary_reset) {
					return XR_DATA_ERROR;
				}

				if (mode >= 2) {
					coder->need_props = false;
					coder->next_sequence = SEQ_PROPERTIES;
				} else if (coder->need_props) {
					return XR_DATA_ERROR;
				} else {
					coder->next_sequence = SEQ_LZMA;
					if (mode == 1)
						xr_lzma_dec_reset_state(
								coder->lzma);
				}

				coder->uncompressed_size =
						(control & 0x1F) << 16;
				coder->sequence = SEQ_UNCOMPRESSED_1;
			} else {
				if (control > 0x02)
					return XR_DATA_ERROR;

				if (control == 0x01) {
					xr_dict_reset(dict);
					coder->need_dictionary_reset = false;
					coder->need_props = true;
				} else if (coder->need_dictionary_reset) {
					return XR_DATA_ERROR;
				}

				coder->uncompressed_size = 0;
				coder->next_sequence = SEQ_COPY;
				coder->sequence = SEQ_UNCOMPRESSED_1;
			}
			break;
		}

		case SEQ_UNCOMPRESSED_1:
			coder->uncompressed_size += (uint32_t)in[(*in_pos)++]
					<< 8;
			coder->sequence = SEQ_UNCOMPRESSED_2;
			break;

		case SEQ_UNCOMPRESSED_2:
			coder->uncompressed_size += (uint32_t)in[(*in_pos)++] + 1;
			coder->sequence = coder->next_sequence == SEQ_COPY
					? SEQ_COPY : SEQ_COMPRESSED_0;
			break;

		case SEQ_COMPRESSED_0:
			coder->compressed_size = (uint32_t)in[(*in_pos)++] << 8;
			coder->sequence = SEQ_COMPRESSED_1;
			break;

		case SEQ_COMPRESSED_1:
			coder->compressed_size += (uint32_t)in[(*in_pos)++] + 1;
			xr_lzma_dec_reset_rc(coder->lzma);
			xr_lzma_dec_set_uncompressed(coder->lzma,
					coder->uncompressed_size, false);
			coder->sequence = coder->next_sequence;
			break;

		case SEQ_PROPERTIES:
			if (!xr_lzma_dec_set_props_byte(coder->lzma,
					in[*in_pos]))
				return XR_DATA_ERROR;
			++*in_pos;
			xr_lzma_dec_reset_state(coder->lzma);
			xr_lzma_dec_set_uncompressed(coder->lzma,
					coder->uncompressed_size, false);
			coder->sequence = SEQ_LZMA;
			break;

		case SEQ_LZMA: {
			const size_t in_start = *in_pos;
			size_t limit = in_size;
			bool chunk_eof = false;

			if ((uint64_t)(in_size - *in_pos)
					>= (uint64_t)coder->compressed_size) {
				limit = *in_pos + coder->compressed_size;
				chunk_eof = true;
			}

			const xr_ret ret = xr_lzma_dec_code(coder->lzma, dict,
					in, in_pos, limit,
					chunk_eof || eof);

			const size_t in_used = *in_pos - in_start;
			if (in_used > coder->compressed_size)
				return XR_DATA_ERROR;
			coder->compressed_size -= (uint32_t)in_used;

			if (ret == XR_STREAM_END) {
				if (coder->compressed_size != 0)
					return XR_DATA_ERROR;
				if (!xr_lzma_dec_rc_finished(coder->lzma))
					return XR_DATA_ERROR;
				coder->sequence = SEQ_CONTROL;
				break;
			}

			if (ret != XR_OK)
				return ret;

			return XR_OK;
		}

		case SEQ_COPY: {
			size_t n = in_size - *in_pos;
			const size_t room = dict->limit - dict->pos;
			if (n > room)
				n = room;
			if (n > coder->uncompressed_size)
				n = coder->uncompressed_size;

			if (n > 0) {
				memcpy(dict->buf + dict->pos, in + *in_pos, n);
				dict->pos += n;
				if (dict->pos > dict->full)
					dict->full = dict->pos;
				*in_pos += n;
				coder->uncompressed_size -= (uint32_t)n;
			}

			if (coder->uncompressed_size == 0) {
				/* The LZMA state must be reset after an
				 * uncompressed chunk. */
				xr_lzma_dec_reset_state(coder->lzma);
				coder->sequence = SEQ_CONTROL;
				break;
			}

			return XR_OK;
		}
		}
	}

	return XR_OK;
}

static void lzma2_decoder_end(void *coder_ptr)
{
	lzma2_dec *coder = coder_ptr;
	free(coder->lzma);
	free(coder);
}

static xr_ret lzma2_decoder_init_lz(xr_lz_decoder *lz,
		xr_lz_options *lz_options, const void *opt)
{
	const xr_options_lzma *options = opt;

	if (lz->coder == NULL) {
		lzma2_dec *coder = calloc(1, sizeof(lzma2_dec));
		if (coder == NULL)
			return XR_MEM_ERROR;
		coder->lzma = malloc(xr_lzma_dec_size());
		if (coder->lzma == NULL) {
			free(coder);
			return XR_MEM_ERROR;
		}
		lz->coder = coder;
		lz->code = &lzma2_decode;
		lz->end = &lzma2_decoder_end;
		lz->reset = NULL;
		lz->set_uncompressed = NULL;
	}

	lzma2_dec *coder = lz->coder;
	coder->sequence = SEQ_CONTROL;
	coder->need_props = true;
	coder->need_dictionary_reset = true;
	coder->uncompressed_size = 0;
	coder->compressed_size = 0;

	xr_lzma_dec_init(coder->lzma);
	xr_lzma_dec_reset_state(coder->lzma);

	lz_options->dict_size = options->dict_size;
	lz_options->preset_dict = options->preset_dict;
	lz_options->preset_dict_size = options->preset_dict_size;
	return XR_OK;
}

xr_ret xr_lzma2_decoder_init(xr_next_coder *next, const xr_filter *filters)
{
	return xr_lz_decoder_init(next, filters, &lzma2_decoder_init_lz);
}

uint64_t xr_lzma2_decoder_memusage(const void *opt)
{
	const xr_options_lzma *options = opt;
	return xr_lz_decoder_memusage(options->dict_size)
			+ xr_lzma_dec_size() + sizeof(lzma2_dec);
}

xr_ret xr_lzma2_props_decode(void **options, const uint8_t *props,
		size_t props_size)
{
	if (props_size != 1)
		return XR_OPTIONS_ERROR;
	if (props[0] > 40)
		return XR_OPTIONS_ERROR;

	xr_options_lzma *opt = malloc(sizeof(xr_options_lzma));
	if (opt == NULL)
		return XR_MEM_ERROR;
	memset(opt, 0, sizeof(*opt));

	if (props[0] == 40) {
		opt->dict_size = UINT32_MAX;
	} else {
		opt->dict_size = 2 | ((uint32_t)props[0] & 1);
		opt->dict_size <<= props[0] / 2 + 11;
	}

	opt->lc = XR_LC_DEFAULT;
	opt->lp = XR_LP_DEFAULT;
	opt->pb = XR_PB_DEFAULT;
	*options = opt;
	return XR_OK;
}

