/* Binary range encoder for LZMA.
 *
 * Symbols are queued and only written out in rc_encode(), which lets the
 * caller stop and resume whenever the output buffer becomes full.
 */
#ifndef XZR_RANGE_ENCODER_H
#define XZR_RANGE_ENCODER_H

#include "common.h"
#include "range_decoder.h"

/* An LZMA symbol never needs more queue slots than this. */
#define RC_SYMBOLS_MAX 58

typedef enum {
	RC_BIT_0,
	RC_BIT_1,
	RC_DIRECT_0,
	RC_DIRECT_1,
	RC_FLUSH
} rc_symbol_type;

typedef struct {
	uint64_t low;
	uint64_t cache_size;
	uint32_t range;
	uint8_t cache;
	size_t count;
	size_t pos;
	probability *probs[RC_SYMBOLS_MAX];
	rc_symbol_type symbols[RC_SYMBOLS_MAX];
} xr_range_encoder;

static inline void rc_encoder_reset(xr_range_encoder *rc)
{
	rc->low = 0;
	rc->cache_size = 1;
	rc->range = UINT32_MAX;
	rc->cache = 0;
	rc->count = 0;
	rc->pos = 0;
}

static inline void rce_bit(xr_range_encoder *rc, probability *prob,
		uint32_t bit)
{
	rc->symbols[rc->count] = (rc_symbol_type)bit;
	rc->probs[rc->count] = prob;
	++rc->count;
}

static inline void rce_bittree(xr_range_encoder *rc, probability *probs,
		uint32_t bit_count, uint32_t symbol)
{
	uint32_t model_index = 1;
	do {
		const uint32_t bit = (symbol >> --bit_count) & 1;
		rce_bit(rc, &probs[model_index], bit);
		model_index = (model_index << 1) | bit;
	} while (bit_count != 0);
}

static inline void rce_bittree_reverse(xr_range_encoder *rc,
		probability *probs, uint32_t bit_count, uint32_t symbol)
{
	uint32_t model_index = 1;
	do {
		const uint32_t bit = symbol & 1;
		symbol >>= 1;
		rce_bit(rc, &probs[model_index], bit);
		model_index = (model_index << 1) | bit;
	} while (--bit_count != 0);
}

static inline void rce_direct(xr_range_encoder *rc, uint32_t value,
		uint32_t bit_count)
{
	do {
		rc->symbols[rc->count++] = (rc_symbol_type)
				(RC_DIRECT_0 + ((value >> --bit_count) & 1));
	} while (bit_count != 0);
}

static inline void rce_flush(xr_range_encoder *rc)
{
	for (size_t i = 0; i < 5; ++i)
		rc->symbols[rc->count++] = RC_FLUSH;
}

static inline bool rc_shift_low(xr_range_encoder *rc,
		uint8_t *out, size_t *out_pos, size_t out_size)
{
	if ((uint32_t)(rc->low) < UINT32_C(0xFF000000)
			|| (uint32_t)(rc->low >> 32) != 0) {
		do {
			if (*out_pos == out_size)
				return true;

			out[*out_pos] = (uint8_t)(rc->cache
					+ (uint8_t)(rc->low >> 32));
			++*out_pos;
			rc->cache = 0xFF;
		} while (--rc->cache_size != 0);

		rc->cache = (uint8_t)((rc->low >> 24) & 0xFF);
	}

	++rc->cache_size;
	rc->low = (rc->low & UINT32_C(0x00FFFFFF)) << RC_SHIFT_BITS;
	return false;
}

/* Returns true if the output buffer became full before all queued symbols
 * were written. */
static inline bool rc_encode(xr_range_encoder *rc,
		uint8_t *out, size_t *out_pos, size_t out_size)
{
	while (rc->pos < rc->count) {
		if (rc->range < RC_TOP_VALUE) {
			if (rc_shift_low(rc, out, out_pos, out_size))
				return true;
			rc->range <<= RC_SHIFT_BITS;
		}

		switch (rc->symbols[rc->pos]) {
		case RC_BIT_0: {
			probability prob = *rc->probs[rc->pos];
			rc->range = (rc->range >> RC_BIT_MODEL_TOTAL_BITS)
					* prob;
			prob += (probability)((RC_BIT_MODEL_TOTAL - prob)
					>> RC_MOVE_BITS);
			*rc->probs[rc->pos] = prob;
			break;
		}

		case RC_BIT_1: {
			probability prob = *rc->probs[rc->pos];
			const uint32_t bound = prob * (rc->range
					>> RC_BIT_MODEL_TOTAL_BITS);
			rc->low += bound;
			rc->range -= bound;
			prob -= (probability)(prob >> RC_MOVE_BITS);
			*rc->probs[rc->pos] = prob;
			break;
		}

		case RC_DIRECT_0:
			rc->range >>= 1;
			break;

		case RC_DIRECT_1:
			rc->range >>= 1;
			rc->low += rc->range;
			break;

		case RC_FLUSH:
			/* Prevent further normalisations. */
			rc->range = UINT32_MAX;
			do {
				if (rc_shift_low(rc, out, out_pos, out_size))
					return true;
			} while (++rc->pos < rc->count);

			rc->count = 0;
			rc->pos = 0;
			return false;
		}

		++rc->pos;
	}

	rc->count = 0;
	rc->pos = 0;
	return false;
}

static inline uint64_t rc_pending(const xr_range_encoder *rc)
{
	return rc->cache_size + 5 - 1;
}

/* ---- Price computation ---- */
#define RC_MOVE_REDUCING_BITS 4
#define RC_BIT_PRICE_SHIFT_BITS 4
#define RC_PRICE_TABLE_SIZE (RC_BIT_MODEL_TOTAL >> RC_MOVE_REDUCING_BITS)
#define RC_INFINITY_PRICE (UINT32_C(1) << 30)

extern const uint8_t xr_rc_prices[RC_PRICE_TABLE_SIZE];

static inline uint32_t rc_bit_price(const probability prob, const uint32_t bit)
{
	return xr_rc_prices[(uint32_t)(prob ^ ((UINT32_C(0) - bit)
			& (RC_BIT_MODEL_TOTAL - 1))) >> RC_MOVE_REDUCING_BITS];
}

static inline uint32_t rc_bit_0_price(const probability prob)
{
	return xr_rc_prices[prob >> RC_MOVE_REDUCING_BITS];
}

static inline uint32_t rc_bit_1_price(const probability prob)
{
	return xr_rc_prices[(RC_BIT_MODEL_TOTAL - prob)
			>> RC_MOVE_REDUCING_BITS];
}

static inline uint32_t rc_bittree_price(const probability *const probs,
		const uint32_t bit_levels, uint32_t symbol)
{
	uint32_t price = 0;
	symbol += UINT32_C(1) << bit_levels;

	do {
		const uint32_t bit = symbol & 1;
		symbol >>= 1;
		price += rc_bit_price(probs[symbol], bit);
	} while (symbol != 1);

	return price;
}

static inline uint32_t rc_bittree_reverse_price(const probability *const probs,
		uint32_t bit_levels, uint32_t symbol)
{
	uint32_t price = 0;
	uint32_t model_index = 1;

	do {
		const uint32_t bit = symbol & 1;
		symbol >>= 1;
		price += rc_bit_price(probs[model_index], bit);
		model_index = (model_index << 1) + bit;
	} while (--bit_levels != 0);

	return price;
}

static inline uint32_t rc_direct_price(const uint32_t bits)
{
	return bits << RC_BIT_PRICE_SHIFT_BITS;
}

#endif

