/* Sliding window + match finder used by the LZMA encoder. */
#ifndef XZR_LZ_ENCODER_H
#define XZR_LZ_ENCODER_H

#include "common.h"

typedef struct {
	uint32_t len;
	uint32_t dist;
} xr_match;

typedef struct xr_mf_s xr_mf;

struct xr_mf_s {
	/* Input window */
	uint8_t *buffer;
	uint32_t size;

	uint32_t keep_size_before;
	uint32_t keep_size_after;

	/* Number of bytes that have been dropped off the front of buffer. */
	uint32_t offset;

	uint32_t read_pos;
	uint32_t read_ahead;
	uint32_t read_limit;
	uint32_t write_pos;
	uint32_t pending;

	/* Match finder state */
	uint32_t cyclic_size;
	uint32_t cyclic_pos;
	uint32_t hash_mask;
	uint32_t depth;
	uint32_t nice_len;
	uint32_t match_len_max;
	uint32_t hash_count;
	uint32_t sons_count;
	uint32_t *hash;
	uint32_t *son;

	xr_action action;

	uint32_t (*find)(xr_mf *mf, xr_match *matches);
	void (*skip)(xr_mf *mf, uint32_t num);
};

typedef struct {
	size_t before_size;
	size_t dict_size;
	size_t after_size;
	size_t match_len_max;
	size_t nice_len;
	xr_match_finder match_finder;
	uint32_t depth;
	const uint8_t *preset_dict;
	uint32_t preset_dict_size;
} xr_lz_enc_options;

typedef struct {
	void *coder;
	xr_ret (*code)(void *coder, xr_mf *mf, uint8_t *out, size_t *out_pos,
			size_t out_size);
	void (*end)(void *coder);
	xr_ret (*options_update)(void *coder, const xr_filter *filter);
	xr_ret (*set_out_limit)(void *coder, uint64_t *uncomp_size,
			uint64_t out_limit);
} xr_lz_encoder;

#define EMPTY_HASH_VALUE 0
#define MUST_NORMALIZE_POS UINT32_MAX

xr_ret xr_lz_encoder_init(xr_next_coder *next, const xr_filter *filters,
		xr_ret (*lz_init)(xr_lz_encoder *lz,
			const void *options, xr_lz_enc_options *lz_options));

uint64_t xr_lz_encoder_memusage(const xr_lz_enc_options *lz_options);

/* Match finder entry points. */
uint32_t xr_mf_hc3_find(xr_mf *mf, xr_match *matches);
void xr_mf_hc3_skip(xr_mf *mf, uint32_t amount);
uint32_t xr_mf_hc4_find(xr_mf *mf, xr_match *matches);
void xr_mf_hc4_skip(xr_mf *mf, uint32_t amount);
uint32_t xr_mf_bt2_find(xr_mf *mf, xr_match *matches);
void xr_mf_bt2_skip(xr_mf *mf, uint32_t amount);
uint32_t xr_mf_bt3_find(xr_mf *mf, xr_match *matches);
void xr_mf_bt3_skip(xr_mf *mf, uint32_t amount);
uint32_t xr_mf_bt4_find(xr_mf *mf, xr_match *matches);
