		size_t out_size, xr_action action)
{
	lz_enc_coder *coder = coder_ptr;

	while (*out_pos < out_size
			&& (*in_pos < in_size || action != XR_RUN)) {
		if (coder->mf.action == XR_RUN
				&& coder->mf.read_pos >= coder->mf.read_limit) {
			const xr_ret fret = fill_window(coder, in, in_pos,
					in_size, action);
			if (fret != XR_OK)
				return fret;
		}

		const xr_ret ret = coder->lz.code(coder->lz.coder, &coder->mf,
				out, out_pos, out_size);
		if (ret != XR_OK) {
			coder->mf.action = XR_RUN;
			return ret;
		}
	}

	return XR_OK;
}

static void lz_encoder_end(void *coder_ptr)
{
	lz_enc_coder *coder = coder_ptr;
	xr_next_end(&coder->next);
	free(coder->mf.son);
	free(coder->mf.hash);
	free(coder->mf.buffer);
	if (coder->lz.end != NULL)
		coder->lz.end(coder->lz.coder);
	else
		free(coder->lz.coder);
	free(coder);
}

static xr_ret lz_encoder_update(void *coder_ptr, const xr_filter *filters_null,
		const xr_filter *reversed_filters)
{
	lz_enc_coder *coder = coder_ptr;
	(void)filters_null;
	if (coder->lz.options_update == NULL)
		return XR_PROG_ERROR;
	const xr_ret ret = coder->lz.options_update(coder->lz.coder,
			reversed_filters);
	if (ret != XR_OK)
		return ret;
	return xr_next_filter_update(&coder->next, reversed_filters + 1);
}

static xr_ret lz_encoder_set_out_limit(void *coder_ptr, uint64_t *uncomp_size,
		uint64_t out_limit)
{
	lz_enc_coder *coder = coder_ptr;
	if (coder->lz.set_out_limit == NULL)
		return XR_OPTIONS_ERROR;
	return coder->lz.set_out_limit(coder->lz.coder, uncomp_size, out_limit);
}

/* Computes the hash table size the same way for allocation and for the
 * memory usage reporting. */
static uint32_t hash_size_for(uint32_t hash_bytes, uint32_t dict_size,
		uint32_t *hash_mask_out)
{
	uint32_t hs;

	if (hash_bytes == 2) {
		hs = 0xFFFF;
	} else {
		hs = dict_size - 1;
		hs |= hs >> 1;
		hs |= hs >> 2;
		hs |= hs >> 4;
		hs |= hs >> 8;
		hs >>= 1;
		hs |= 0xFFFF;
		if (hs > (UINT32_C(1) << 24)) {
			if (hash_bytes == 3)
				hs = (UINT32_C(1) << 24) - 1;
			else
				hs >>= 1;
		}
	}

	if (hash_mask_out != NULL)
		*hash_mask_out = hs;

	++hs;
	if (hash_bytes > 2)
		hs += HASH_2_SIZE;
	if (hash_bytes > 3)
		hs += HASH_3_SIZE;

	return hs;
}

static void mf_params(xr_match_finder mf_id, uint32_t *hash_bytes,
		bool *is_bt)
{
	*is_bt = (mf_id & 0x10) != 0;
	*hash_bytes = mf_id & 0x0F;
}

static uint32_t mf_buffer_size(const xr_lz_enc_options *o)
{
	const uint32_t keep_before = (uint32_t)(o->before_size + o->dict_size);
	const uint32_t keep_after = (uint32_t)(o->after_size + o->match_len_max);

	uint32_t reserve = (uint32_t)(o->dict_size / 2);
	if (reserve > (UINT32_C(1) << 30))
		reserve /= 2;

	reserve += (uint32_t)((o->before_size + o->match_len_max
			+ o->after_size) / 2) + (UINT32_C(1) << 19);

	return keep_before + reserve + keep_after;
}

uint64_t xr_lz_encoder_memusage(const xr_lz_enc_options *lz_options)
{
	uint32_t hash_bytes;
	bool is_bt;
	mf_params(lz_options->match_finder, &hash_bytes, &is_bt);

	const uint32_t hs = hash_size_for(hash_bytes,
			(uint32_t)lz_options->dict_size, NULL);
	const uint32_t cyclic_size = (uint32_t)lz_options->dict_size + 1;
	const uint64_t sons = is_bt ? (uint64_t)cyclic_size * 2 : cyclic_size;

	return (uint64_t)mf_buffer_size(lz_options)
			+ (uint64_t)hs * sizeof(uint32_t)
			+ sons * sizeof(uint32_t)
			+ sizeof(lz_enc_coder);
}

static xr_ret lz_encoder_prepare(xr_mf *mf, const xr_lz_enc_options *o)
{
	uint32_t hash_bytes;
	bool is_bt;
	mf_params(o->match_finder, &hash_bytes, &is_bt);

	switch (o->match_finder) {
	case XR_MF_HC3:
		mf->find = &xr_mf_hc3_find;
		mf->skip = &xr_mf_hc3_skip;
		break;
	case XR_MF_HC4:
		mf->find = &xr_mf_hc4_find;
		mf->skip = &xr_mf_hc4_skip;
		break;
	case XR_MF_BT2:
		mf->find = &xr_mf_bt2_find;
		mf->skip = &xr_mf_bt2_skip;
		break;
	case XR_MF_BT3:
		mf->find = &xr_mf_bt3_find;
		mf->skip = &xr_mf_bt3_skip;
		break;
	case XR_MF_BT4:
		mf->find = &xr_mf_bt4_find;
		mf->skip = &xr_mf_bt4_skip;
		break;
	default:
		return XR_OPTIONS_ERROR;
	}

	mf->keep_size_before = (uint32_t)(o->before_size + o->dict_size);
	mf->keep_size_after = (uint32_t)(o->after_size + o->match_len_max);
	mf->match_len_max = (uint32_t)o->match_len_max;
	mf->nice_len = (uint32_t)o->nice_len;
	mf->cyclic_size = (uint32_t)o->dict_size + 1;

	mf->depth = o->depth;
	if (mf->depth == 0) {
		mf->depth = 16 + (mf->nice_len / 2);
		if (!is_bt)
			mf->depth /= 2;
	}

	const uint32_t new_size = mf_buffer_size(o);
	uint32_t hash_mask;
	const uint32_t hs = hash_size_for(hash_bytes,
			(uint32_t)o->dict_size, &hash_mask);

	if (mf->buffer == NULL || mf->size != new_size) {
		free(mf->buffer);
		mf->buffer = malloc(new_size);
		if (mf->buffer == NULL) {
			mf->size = 0;
			return XR_MEM_ERROR;
		}
		mf->size = new_size;
	}

	const uint32_t old_count = mf->hash_count;
	const uint32_t old_sons = mf->sons_count;
	mf->hash_count = hs;
	mf->hash_mask = hash_mask;
	mf->sons_count = is_bt ? mf->cyclic_size * 2 : mf->cyclic_size;

	if (mf->hash == NULL || old_count != mf->hash_count) {
		free(mf->hash);
		mf->hash = malloc((size_t)mf->hash_count * sizeof(uint32_t));
		if (mf->hash == NULL)
			return XR_MEM_ERROR;
	}
	if (mf->son == NULL || old_sons != mf->sons_count) {
		free(mf->son);
		mf->son = malloc((size_t)mf->sons_count * sizeof(uint32_t));
		if (mf->son == NULL)
			return XR_MEM_ERROR;
	}

	return XR_OK;
}

static void lz_encoder_reset(xr_mf *mf, const xr_lz_enc_options *o)
{
	mf->offset = 0;
	mf->read_pos = 0;
	mf->read_ahead = 0;
	mf->read_limit = 0;
	mf->write_pos = 0;
	mf->pending = 0;
	mf->cyclic_pos = 0;
	mf->action = XR_RUN;

	for (uint32_t i = 0; i < mf->hash_count; ++i)
		mf->hash[i] = EMPTY_HASH_VALUE;

	if (o->preset_dict != NULL && o->preset_dict_size > 0) {
		uint32_t copy_size = o->preset_dict_size;
		if (copy_size > o->dict_size)
			copy_size = (uint32_t)o->dict_size;
		memcpy(mf->buffer, o->preset_dict + o->preset_dict_size
				- copy_size, copy_size);
		mf->write_pos = copy_size;
		mf->skip(mf, copy_size);
		mf->read_ahead = 0;
	}
}

xr_ret xr_lz_encoder_init(xr_next_coder *next, const xr_filter *filters,
		xr_ret (*lz_init)(xr_lz_encoder *lz, const void *options,
			xr_lz_enc_options *lz_options))
{
	lz_enc_coder *coder = next->coder;

	if (coder == NULL || next->code != &lz_encode) {
		coder = calloc(1, sizeof(lz_enc_coder));
		if (coder == NULL)
			return XR_MEM_ERROR;
		next->coder = coder;
		next->code = &lz_encode;
		next->end = &lz_encoder_end;
		coder->next = XR_NEXT_CODER_INIT;
	}

	xr_lz_enc_options lz_options;
	memset(&lz_options, 0, sizeof(lz_options));

	xr_ret ret = lz_init(&coder->lz, filters[0].options, &lz_options);
	if (ret != XR_OK)
		return ret;

	ret = lz_encoder_prepare(&coder->mf, &lz_options);
	if (ret != XR_OK)
		return ret;

	lz_encoder_reset(&coder->mf, &lz_options);

	return xr_next_filter_init(&coder->next, filters + 1, true);
}

/* Exposed so the LZMA2 encoder can update options mid-stream. */
xr_ret xr_lz_encoder_options_update(void *coder_ptr,
		const xr_filter *reversed_filters)
{
	return lz_encoder_update(coder_ptr, NULL, reversed_filters);
}

xr_ret xr_lz_encoder_set_out_limit(void *coder_ptr, uint64_t *uncomp_size,
		uint64_t out_limit)
{
	return lz_encoder_set_out_limit(coder_ptr, uncomp_size, out_limit);
}

/* ---- Position/normalisation helpers shared by the match finders ---- */
static void normalize(xr_mf *mf)
{
	const uint32_t subvalue = MUST_NORMALIZE_POS - mf->cyclic_size;

	for (uint32_t i = 0; i < mf->hash_count; ++i) {
		if (mf->hash[i] <= subvalue)
			mf->hash[i] = EMPTY_HASH_VALUE;
		else
			mf->hash[i] -= subvalue;
	}

	for (uint32_t i = 0; i < mf->sons_count; ++i) {
		if (mf->son[i] <= subvalue)
			mf->son[i] = EMPTY_HASH_VALUE;
		else
			mf->son[i] -= subvalue;
	}

	mf->offset -= subvalue;
}

void xr_mf_move_pos(xr_mf *mf)
{
	if (++mf->cyclic_pos == mf->cyclic_size)
		mf->cyclic_pos = 0;

	++mf->read_pos;

	if (mf->read_pos + mf->offset == MUST_NORMALIZE_POS)
		normalize(mf);
}

uint32_t xr_mf_find(xr_mf *mf, uint32_t *count_ptr, xr_match *matches)
{
	const uint32_t count = mf->find(mf, matches);
	uint32_t len_best = 0;

	if (count > 0) {
		len_best = matches[count - 1].len;

		if (len_best == mf->nice_len) {
			uint32_t limit = mf_avail(mf) + 1;
			if (limit > mf->match_len_max)
				limit = mf->match_len_max;

			const uint8_t *p1 = mf_ptr(mf) - 1;
			const uint8_t *p2 = p1 - matches[count - 1].dist - 1;
			len_best = xr_memcmplen(p1, p2, len_best, limit);
		}
	}

	*count_ptr = count;
	++mf->read_ahead;
	return len_best;
}

