42	static xr_match *hc_find_func(const uint32_t len_limit, const uint32_t pos,
43			const uint8_t *const cur, uint32_t cur_match, uint32_t depth,
44			uint32_t *const son, const uint32_t cyclic_pos,
45			const uint32_t cyclic_size, xr_match *matches,
46			uint32_t len_best)
47	{
48		son[cyclic_pos] = cur_match;
49	
50		while (true) {
51			const uint32_t delta = pos - cur_match;
52			if (depth-- == 0 || delta >= cyclic_size)
53				return matches;
54	
55			const uint8_t *const pb = cur - delta;
56			cur_match = son[cyclic_pos - delta
57					+ (delta > cyclic_pos ? cyclic_size : 0)];
58	
59			if (pb[len_best] == cur[len_best] && pb[0] == cur[0]) {
60				uint32_t len = xr_memcmplen(pb, cur, 1, len_limit);
61	
62				if (len_best < len) {
63					len_best = len;
64					matches->len = len;
65					matches->dist = delta - 1;
66					++matches;
67	
68					if (len == len_limit)
69						return matches;
70				}
71			}
72		}
73	}
