138	{
139		header_find(false, 4);
140	
141		hash_4_calc();
142	
143		uint32_t delta2 = pos - mf->hash[hash_2_value];
144		const uint32_t delta3 = pos - mf->hash[FIX_3_HASH_SIZE + hash_3_value];
145		const uint32_t cur_match = mf->hash[FIX_4_HASH_SIZE + hash_value];
146	
147		mf->hash[hash_2_value] = pos;
148		mf->hash[FIX_3_HASH_SIZE + hash_3_value] = pos;
149		mf->hash[FIX_4_HASH_SIZE + hash_value] = pos;
150	
151		uint32_t len_best = 1;
152	
153		if (delta2 < mf->cyclic_size && *(cur - delta2) == *cur) {
154			len_best = 2;
155			matches[0].len = 2;
156			matches[0].dist = delta2 - 1;
157			matches_count = 1;
158		}
159	
160		if (delta2 != delta3 && delta3 < mf->cyclic_size
161				&& *(cur - delta3) == *cur) {
162			len_best = 3;
163			matches[matches_count++].dist = delta3 - 1;
164			delta2 = delta3;
165		}
166	
167		if (matches_count != 0) {
168			len_best = xr_memcmplen(cur, cur - delta2, len_best, len_limit);
169	
170			matches[matches_count - 1].len = len_best;
171	
172			if (len_best >= len_limit) {
173				mf->son[mf->cyclic_pos] = cur_match;
174				xr_mf_move_pos(mf);
175				return matches_count;
176			}
177		}
178	
179		if (len_best < 3)
180			len_best = 3;
181	
182		matches_count = (uint32_t)(hc_find_func(len_limit, pos, cur, cur_match,
183				mf->depth, mf->son, mf->cyclic_pos, mf->cyclic_size,
184				matches + matches_count, len_best) - matches);
185		xr_mf_move_pos(mf);
186		return matches_count;
187	}
